def car_pooling(trips, capacity):
    events = {}
    for n, a, b in trips:
        events[a] = events.get(a, 0) + n
        events[b] = events.get(b, 0) - n
    cur = 0
    for t in sorted(events):
        cur += events[t]
        if cur > capacity:
            return False
    return True

