bool carPooling(vector<vector<int>>& tr, int cap) {
    map<int,long long> ev; for (auto& t : tr) { ev[t[1]] += t[0]; ev[t[2]] -= t[0]; }
    long long cur = 0; for (auto& [x, d] : ev) { cur += d; if (cur > cap) return false; } return true;
}
